const VERSION='submovie-security-medium-20261021-v1';
function canonical(value){return value.toString('utf8').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');}
function hash(value){return crypto.createHash('sha256').update(value).digest('hex');}
function target(root,name){
 if(!/^[a-zA-Z0-9_.\-/]+$/.test(name)||name.split('/').includes('..')||path.isAbsolute(name))throw new Error('不正な保存先です。');
 const full=path.join(root,...name.split('/'));let here=root;
 for(const part of name.split('/')){here=path.join(here,part);if(fs.lstatSync(here,{throwIfNoEntry:false})?.isSymbolicLink())throw new Error('リンクを指す保存先には書き込めません: '+name);}
 return full;
}
function syntax(text,name,module=false){const r=spawnSync(process.execPath,['--check',...(module?['--input-type=module']:[])],{input:text,encoding:'utf8',maxBuffer:1024*1024});if(r.status!==0)throw new Error('構文確認に失敗しました: '+name+'\n'+(r.stderr||r.error?.message||''));}
